import io
import os
import sqlite3
from sync.client import DEFAULT_BASE_URL, VendorClient

records = list(VendorClient(os.environ.get('VENDOR_API', DEFAULT_BASE_URL), notices=io.StringIO()).iter_items())
c = sqlite3.connect('data/catalog.db')
before = sqlite3.connect('data/catalog.before-v2-sync.db')
rows = {r[0]: r for r in c.execute('SELECT * FROM products')}
old_rows = {r[0]: r for r in before.execute('SELECT * FROM products')}
seen = {r['sku'] for r in records}
for r in records:
    old = old_rows.get(r['sku'])
    if old and old[3] == 'manual':
        assert rows[r['sku']] == old
    elif r.get('deleted'):
        assert r['sku'] not in rows
    else:
        assert rows[r['sku']] == (r['sku'], r['name'], r['price_paise'], 'vendor', r['updated_at'])
for sku, row in old_rows.items():
    if row[3] == 'manual' or sku not in seen:
        assert rows[sku] == row
assert c.execute('PRAGMA integrity_check').fetchone() == ('ok',)
print('Verified all feed records, manual preservation, unmentioned SKU preservation, and DB integrity.')
print('Counts:', c.execute('SELECT source, COUNT(*) FROM products GROUP BY source').fetchall())
print('Sync state:', c.execute('SELECT * FROM sync_state').fetchall())
